def load():
    import os,re
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def transform(g):
    h,w=len(g),len(g[0])
    from collections import defaultdict
    cells=defaultdict(list)
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v: cells[v].append((i,j))
    o=[row[:] for row in g]
    for v,ps in cells.items():
        if len(ps)==2:
            (a,b)=ps
            va,vb=a[0],b[0]; ca,cb=a[1],b[1]
            # vertical at a's column between rows, horizontal at b's row between cols
            for i in range(min(va,vb),max(va,vb)+1): o[i][ca]=v
            for j in range(min(ca,cb),max(ca,cb)+1): o[vb][j]=v
        else:
            i,j=ps[0]
            for r in range(i,h): o[r][j]=v
    return o
